"use client";

import { CartesianGrid, Line, LineChart, XAxis, YAxis } from "recharts";
import { Card, CardContent, CardHeader, CardTitle } from "../../ui/card/card";
import { type ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent } from "../../ui/chart/chart";
import styles from "./card-traffic.module.css";

export type TrafficDataPoint = {
  /** ISO date (YYYY-MM-DD), or a numeric day label. */
  date: string | number;
  desktop: number;
  mobile: number;
};

export type CardTrafficProps = {
  data: TrafficDataPoint[];
  bounceRate?: number;
  conversionRate?: number;
};

const formatDate = (value: unknown) => {
  if (typeof value === "number") {
    return `Day ${value}`;
  }
  const date = new Date(String(value));
  return Number.isNaN(date.getTime())
    ? String(value)
    : date.toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
};

const chartConfig = {
  mobile: {
    label: "Mobile",
    color: "var(--chart-1)",
  },
  desktop: {
    label: "Desktop",
    color: "var(--chart-2)",
  },
} satisfies ChartConfig;

export function CardTraffic({ data, bounceRate, conversionRate }: CardTrafficProps) {
  const mobile = data.reduce((sum, point) => sum + point.mobile, 0);
  const desktop = data.reduce((sum, point) => sum + point.desktop, 0);
  return (
    <Card
      className={styles.cardContainer}
      style={{
        maxWidth: "600px",
        width: "100%",
      }}
    >
      <CardHeader>
        <CardTitle>Website Traffic</CardTitle>
      </CardHeader>
      <CardContent className={styles.chartContainer}>
        <div style={{ width: "100%", height: "100%" }}>
          <ChartContainer config={chartConfig}>
            <LineChart data={data}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="date" hide={true} tickFormatter={formatDate} />
              <YAxis hide={true} />
              <ChartTooltip content={<ChartTooltipContent labelFormatter={formatDate} />} />
              <Line
                animationDuration={800}
                dataKey="mobile"
                dot={false}
                stroke="var(--color-mobile)"
                strokeWidth={2}
                type="monotone"
              />
              <Line
                animationBegin={200}
                animationDuration={800}
                dataKey="desktop"
                dot={false}
                stroke="var(--color-desktop)"
                strokeWidth={2}
                type="monotone"
              />
            </LineChart>
          </ChartContainer>
        </div>
      </CardContent>

      <div className={styles.statsGrid}>
        <div className={styles.statCard}>
          <div className={styles.statHeader}>
            <span className={styles.statLabel}>Mobile</span>
          </div>
          <span className={styles.statNumber}>{mobile.toLocaleString("en-US")}</span>
        </div>

        <div className={styles.statCard}>
          <div className={styles.statHeader}>
            <span className={styles.statLabel}>Desktop</span>
          </div>
          <span className={styles.statNumber}>{desktop.toLocaleString("en-US")}</span>
        </div>

        <div className={styles.statCard}>
          <div className={styles.statHeader}>
            <span className={styles.statLabel}>Bounce Rate</span>
          </div>
          <span className={styles.statNumber}>{bounceRate === undefined ? "Not provided" : `${bounceRate}%`}</span>
        </div>

        <div className={styles.statCard}>
          <div className={styles.statHeader}>
            <span className={styles.statLabel}>Conversion</span>
          </div>
          <span className={styles.statNumber}>
            {conversionRate === undefined ? "Not provided" : `${conversionRate}%`}
          </span>
        </div>
      </div>
    </Card>
  );
}

.cardContainer {
  width: 100%;
  max-width: 600px;
}

.chartContainer {
  height: 200px;
  padding: 0;
}

.statsGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  border-top: 0.5px solid oklch(from var(--border) l c h / 0.7);
  margin: 0 -24px -24px -24px;
}

.statCard {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-right: 0.5px solid oklch(from var(--border) l c h / 0.7);
  border-bottom: 0.5px solid oklch(from var(--border) l c h / 0.7);
}

.statCard:nth-child(2n) {
  border-right: none;
}

.statCard:nth-child(n + 3) {
  border-bottom: none;
}

@media (max-width: 640px) {
  .cardContainer {
    max-width: 100%;
  }

  .chartContainer {
    height: 200px;
  }

  .statsGrid {
    margin: 0 -20px -20px -20px;
  }

  .statCard {
    padding: 1rem;
    gap: 0.5rem;
  }

  .statLabel {
    font-size: 0.875rem;
  }

  .statNumber {
    font-size: 1.75rem;
    font-weight: 700;
  }
}

@media (max-width: 400px) {
  .statsGrid {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
    margin: 0 -20px -20px -20px;
  }

  .statCard {
    border-right: none;
    border-bottom: 1px solid var(--border);
    padding: 1rem;
  }

  .statCard:nth-child(2n) {
    border-right: none;
  }

  .statCard:nth-child(n + 3) {
    border-bottom: 1px solid var(--border);
  }

  .statCard:last-child {
    border-bottom: none;
  }

  .statNumber {
    font-size: 1.5rem;
  }
}

.statHeader {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.statLabel {
  font-size: 14px;
  line-height: 20px;
  color: var(--muted-foreground);
  font-weight: 500;
}

.statNumber {
  font-size: 32px;
  font-weight: 700;
  color: var(--foreground);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
